def clamp(x: int, lo: int, hi: int) -> int:
    if x < lo:
        return lo
    if x > hi:
        return hi
    return x

def contains(xs: list[int], x: int) -> bool:
    for item in xs:
        if item == x:
            return True
    return False

def factorial(n: int) -> int:
    result = 1
    for i in range(2, n + 1):
        result *= i
    return result

def gcd(a: int, b: int) -> int:
    while b:
        a, b = b, a % b
    return a

