def length(xs: list[int]) -> int:
    count = 0
    for _ in xs:
        count += 1
    return count

def safe_div(a: int, b: int) -> int | None:
    if b == 0:
        return None
    return a // b

def sum_list(xs: list[int]) -> int:
    total = 0
    for x in xs:
        total += x
    return total
